#include <iostream>
using namespace std;

int main() {
    // Downwards.
    for (int i = 5; i >= 1; i--) {
        cout << i << " ";
    }
    cout << endl;

    // In steps of 2.
    for (int i = 0; i <= 10; i += 2) {
        cout << i << " ";
    }
    cout << endl;

    // The 7 times table.
    for (int i = 1; i <= 5; i++) {
        cout << "7 x " << i << " = " << 7 * i << endl;
    }
    return 0;
}

