#include <iostream>
using namespace std;

int main() {
    cout << "How many numbers? ";
    int count;
    cin >> count;

    int total = 0;

    for (int i = 1; i <= count; i++) {
        cout << "Number " << i << "? ";
        int n;
        cin >> n;
        total += n;
    }

    cout << "Total: " << total << endl;
    cout << "Average: " << static_cast<double>(total) / count << endl;
    return 0;
}

